const ANNA_PAGES=[['overview','路线攻略','首页、培养计划与阵容',['首页','培养计划','阵容','路线']],['characters','全角色图鉴','63 名角色的成长与培养',['人物','图鉴','角色列表']],['recruit','招募与声望','各路线入队条件与门槛',['挖角','挖人','入队','声望']],['gifts','礼物与喜好','124 件礼物分类、价格与角色喜好反查',['礼物','送礼','好感','喜好','特芙','生日']],['classes','职业资格','60 种职业的资格与成长修正',['职业','转职','成长率']],['skills','特技与战技','技能效果与获取条件',['技能','战技','特技']],['training','技能与斗技场','训练项目与技能停止线',['斗技场','训练','停止线','刷级']],['equipment','装备与材料','武器、装备、锻造石材与兑换材料',['装备','武器','材料','兑换','锻造','强化','商店']],['map','探索大地图','采集点、店铺与地点',['地图','采集','地点','点位']],['guides','攻略文章','机制解释与培养长文',['攻略','文章','机制','继承','周目']],['preferences','偏好与规划','关注角色与队伍规划',['偏好','关注','我的队伍']],['compare','角色对比','并排比较角色成长',['对比','比较']],['calculator','自定义养成','自定义职业路线计算',['计算器','自定义','养成方案']],['sources','资料来源','数据出处与编辑方法',['来源','出处']]];

// 索引(CATALOG 已冻结,另建数组;首次打开时懒构建)。
let annaIndex=null;
function annaPinyinOf(text){let fulls=[''],acrs=[''];for(const ch of String(text||'')){let rs=null;const fixed=ANNA_PINYIN_FIX[ch];if(fixed||ANNA_PINYIN[ch]){rs=[fixed||ANNA_PINYIN[ch]];if(ANNA_PINYIN_ALT[ch])rs.push(ANNA_PINYIN_ALT[ch])}else if(/[a-z0-9]/i.test(ch))rs=[ch.toLowerCase()];if(!rs)continue;fulls=fulls.flatMap(f=>rs.map(r=>f+r)).slice(0,16);acrs=acrs.flatMap(a=>rs.map(r=>a+r[0])).slice(0,16)}return {full:[...new Set(fulls)],acr:[...new Set(acrs)]}}
function annaEntry(kind,id,title,sub,alias=[],hay=''){const p=annaPinyinOf(title);return {kind,id,title:String(title),sub:String(sub||''),alias:alias.filter(Boolean).map(String),acr:p.acr,pinyin:p.full,hay:String(hay||'').toLowerCase()}}
function buildAnnaIndex(){
 if(annaIndex)return annaIndex;
 const idx=[];
 for(const [id,title,sub,kw]of ANNA_PAGES)idx.push(annaEntry('page',id,title,sub,kw,kw.join(' ')));
 for(const c of DB.characters)idx.push(annaEntry('character',c.id,c.cn,`${c.rating} · ${c.role}`,[c.name,c.alias],[c.role,c.personalSkill,c.personalSkillEffect,c.birthday?'生日 '+c.birthday:'',...(c.giftRecs||[]).map(g=>g.name),...c.joinDetails.flatMap(j=>[j.answers,j.deadline,j.gift?.name]).filter(Boolean)].filter(Boolean).join(' ')));
 for(const cl of DB.classes)idx.push(annaEntry('class',cl.cn,cl.cn,cl.col_1,[cl.title],[cl.col_37||'',cl.col_2||'',cl.unlock||'',(cl.allowedSkills||[]).join(' ')].join(' ')));
 for(const a of CATALOG.abilities)idx.push(annaEntry('ability',a.id,a.name,a.type,[],a.descriptions.map(d=>d.text).join(' ')));
 for(const e of EQUIPMENT)idx.push(annaEntry('equipment',e.id,e.name,[e.type,e.phase].filter(Boolean).join(' · '),[e.original,...(e.aliases||[])],[e.effect,e.purpose,e.type].filter(Boolean).join(' ')));
 for(const m of materialExchangeIndex())idx.push(annaEntry('material',m.name,m.name,`${m.kind||'材料'} · ${(m.allUses||m.uses).length} 项用途${m.where.length?' · '+m.where.slice(0,2).join('、'):''}`,m.aliases,m.where.join(' ')));
 if(Array.isArray(CATALOG.gifts)&&CATALOG.gifts.length){
  for(const g of CATALOG.gifts){
   const who=(g.likedBy||[]).map(id=>DB.characters.find(c=>c.id===id)?.cn).filter(Boolean);
   idx.push(annaEntry('gift',g.id,g.name,[g.category,g.price?g.price+'G':'非卖品',who.length?who.slice(0,3).join('、')+' 最爱':''].filter(Boolean).join(' · '),[g.nameEn||'',g.category],[g.category,...(g.sources||[]),...who,'礼物'].join(' ')));
  }
 }else{
  const giftMap=new Map();
  for(const c of DB.characters){
   for(const g of (c.giftRecs||[])){const e=giftMap.get(g.name)||{name:g.name,price:0,place:'',who:[]};e.price=e.price||g.price;e.who.push(c.cn);giftMap.set(g.name,e)}
   for(const j of c.joinDetails)if(j.gift){const e=giftMap.get(j.gift.name)||{name:j.gift.name,price:0,place:'',who:[]};e.price=e.price||j.gift.price||0;e.place=e.place||j.gift.place||'';e.who.push(c.cn);giftMap.set(j.gift.name,e)}
  }
  for(const g of giftMap.values())idx.push(annaEntry('gift',g.name,g.name,[g.price?g.price+'G':'',g.place,[...new Set(g.who)].slice(0,3).join('、')+' 喜欢'].filter(Boolean).join(' · '),[],[...new Set(g.who)].join(' ')+' 礼物'));
 }
 const seen=new Set();
 for(const t of CATALOG.mapTerms){if(!t.name||seen.has(t.name))continue;seen.add(t.name);idx.push(annaEntry('place',t.name,t.name,t.info,[],t.info))}
 for(const a of ARTICLES)idx.push(annaEntry('article',a.id,a.title,a.category,a.tags||[],[a.summary,...(a.sections||[]).map(s=>s.heading)].join(' ')));
 annaIndex=idx;return idx;
}

// 查询归一化与匹配:去疑问词/语气词→繁折简→分词→同义词变体;词间 AND、变体间 OR。
function annaFold(q){let s=String(q||'').trim().toLowerCase(),out='';for(const ch of s)out+=ANNA_TRAD[ch]||ch;return out.replace(/^((?:请问一下|请问|怎么|如何|什么|哪里|哪儿|在哪|哪个|谁|多少))+/,'').replace(/(吗|呢|啊|呀|吧)+$/,'')}
function annaVariants(word){const syn=ANNA_SYNONYMS[word];return syn&&syn!==word?[word,syn]:[word]}
function annaScore(e,v){
 const t=e.title.toLowerCase();
 if(t===v)return 100;
 for(const a of e.alias)if(a.toLowerCase()===v)return 95;
 if(t.startsWith(v))return 80;
 const ascii=/^[\x20-\x7e]+$/.test(v);
 if(ascii&&v.length>=2){for(const a of e.acr)if(a===v)return 78;for(const a of e.acr)if(a.startsWith(v))return 72}
 const pos=t.indexOf(v);if(pos>=0)return 60-Math.min(pos,10);
 for(const a of e.alias)if(a.toLowerCase().includes(v))return 55;
 if(ascii&&v.length>=3)for(const p of e.pinyin)if(p.includes(v))return 50;
 if(e.hay.includes(v))return 20;
 return -1;
}
function annaSearch(q){
 const norm=annaFold(q),empty={groups:[],flat:[],best:null,total:0,norm};
 if(!norm)return empty;
 const words=norm.split(/\s+/).filter(Boolean),scored=[];
 for(const e of buildAnnaIndex()){
  let sum=0,hitCount=0;
  for(const w of words){let best=-1;for(const v of annaVariants(w))best=Math.max(best,annaScore(e,v));if(best>=0){hitCount++;sum+=best}}
  if(hitCount===words.length)scored.push({e,score:sum/words.length+(ANNA_KIND_WEIGHT[e.kind]||0)+10});
  else if(hitCount>0&&words.length>1)scored.push({e,score:(sum/words.length)*(hitCount/words.length)+(ANNA_KIND_WEIGHT[e.kind]||0)});
 }
 if(!scored.length&&norm.length>=2&&!/^[\x20-\x7e]+$/.test(norm)){
  for(const e of buildAnnaIndex()){
   let maxS=-1;
   for(let len=Math.min(4,norm.length);len>=2;len--){
    for(let i=0;i<=norm.length-len;i++){
     const sub=norm.slice(i,i+len);
     for(const v of annaVariants(sub)){const s=annaScore(e,v);if(s>=55)maxS=Math.max(maxS,s*(len/norm.length))}
    }
   }
   if(maxS>=0)scored.push({e,score:maxS+(ANNA_KIND_WEIGHT[e.kind]||0)});
  }
 }
 scored.sort((a,b)=>b.score-a.score||a.e.title.length-b.e.title.length);
 const byKind={};for(const [k]of ANNA_GROUPS)byKind[k]=[];
 for(const s of scored)if(byKind[s.e.kind].length<5)byKind[s.e.kind].push(s);
 const groups=[],flat=[];let count=0;
 for(const [kind,label]of ANNA_GROUPS){const items=byKind[kind].filter(()=>count<24&&(count++,true));if(items.length){groups.push({kind,label,items});flat.push(...items)}}
 return {groups,flat,best:flat[0]||null,total:scored.length,norm};
}

// 弹层 UI:复用 openGuideDialog 的焦点保存与背景锁定;结果动作全部复用现有导航;同时接入 AI 提问对话。
let annaOwnsLock=false,annaFlat=[],annaActive=-1,annaGreetTimer=null,annaDebounce=null,annaBackdropDown=false,annaDialogAiHtml='',annaDialogAiQuery='',annaDialogAsking=false;
function annaReduced(){return typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches}
function annaStatsText(){return ''}
function annaMark(text,norm){if(!norm||/^[\x20-\x7e]+$/.test(norm))return esc(text);const i=text.toLowerCase().indexOf(norm);return i<0?esc(text):esc(text.slice(0,i))+'<mark>'+esc(text.slice(i,i+norm.length))+'</mark>'+esc(text.slice(i+norm.length))}
function annaGreeting(){
 const h=$('#annaSearch')?.querySelector('h2');if(!h)return;
 const line=ANNA_GREETS[Math.floor(Math.random()*ANNA_GREETS.length)];
 if(typeof clearInterval==='function')clearInterval(annaGreetTimer);
 if(annaReduced()||typeof setInterval!=='function'){h.textContent=line;return}
 h.textContent='';h.classList.add('anna-typing');let i=0;
 annaGreetTimer=setInterval(()=>{i++;h.textContent=line.slice(0,i);if(i>=line.length){clearInterval(annaGreetTimer);h.classList.remove('anna-typing')}},32);
}
async function askAnnaInDialog(rawQ){
 const input=$('#annaInput'),box=$('#annaResults');
 const q=String(rawQ!==undefined?rawQ:(input?.value||'')).trim();
 if(!q||annaDialogAsking)return;
 const configured=typeof annaLlmConfigured==='function'?annaLlmConfigured():(typeof annaLlmReady==='function'&&annaLlmReady());
 if(!configured){
  if(typeof openAnnaLlmSettings==='function')openAnnaLlmSettings();
  return;
 }
 if(typeof annaLlmMode==='function'&&annaLlmMode()==='search'&&typeof annaLlmSetMode==='function')annaLlmSetMode('ai');
 annaDialogAsking=true;
 annaDialogAiQuery=q;
 annaDialogAiHtml='<div class="anna-dialog-ai"><p class="anna-ask-none anna-ask-loading">安娜正在翻阅账本…</p></div>';
 renderAnnaResults();
 try{
  let stepList=[];
  const r=await annaAgentAsk(q,name=>{
   stepList.push(name);
   annaDialogAiHtml=`<div class="anna-dialog-ai"><p class="anna-ask-none anna-ask-loading">${esc((window.ANNA_TOOL_LABEL&&window.ANNA_TOOL_LABEL[name])||'查询中')}…</p></div>`;
   const aiBox=box?.querySelector('.anna-dialog-ai');
   if(aiBox)aiBox.outerHTML=annaDialogAiHtml;else renderAnnaResults();
  },partial=>{
   const stepsText=stepList.length?`<small class="anna-agent-steps">已核对：${[...new Set(stepList)].map(n=>esc((window.ANNA_TOOL_LABEL&&window.ANNA_TOOL_LABEL[n])||n)).join(' · ')}</small>`:'';
   annaDialogAiHtml=`<div class="anna-dialog-ai"><div class="anna-agent-answer is-streaming"><div class="anna-agent-head"><b>安娜的解答</b>${stepsText}</div><div class="anna-agent-body"><p>${annaAgentRender(partial)}<span class="anna-stream-caret">▍</span></p></div></div></div>`;
   const aiBox=box?.querySelector('.anna-dialog-ai');
   if(aiBox)aiBox.outerHTML=annaDialogAiHtml;else renderAnnaResults();
  });
  annaDialogAiHtml=`<div class="anna-dialog-ai"><div class="anna-agent-answer"><div class="anna-agent-head"><b>安娜的解答</b>${r.steps.length?`<small class="anna-agent-steps">已核对：${[...new Set(r.steps)].map(n=>esc((window.ANNA_TOOL_LABEL&&window.ANNA_TOOL_LABEL[n])||n)).join(' · ')}</small>`:''}<button type="button" class="anna-ai-close" data-anna-ai-clear aria-label="收起回答">收起</button></div><div class="anna-agent-body"><p>${annaAgentRender(r.answer)}</p></div></div></div>`;
 }catch(err){
  annaDialogAiHtml=`<div class="anna-dialog-ai"><p class="anna-agent-error">${esc('接口暂未响应（'+(err&&err.message||err)+'），以下为账本直接匹配：')}</p></div>`;
 }finally{
  annaDialogAsking=false;
  renderAnnaResults();
 }
}
function renderAnnaResults(){
 const input=$('#annaInput'),box=$('#annaResults');if(!input||!box)return;
 const raw=input.value.trim(),res=annaSearch(raw);
 annaFlat=res.flat;annaActive=-1;input.removeAttribute('aria-activedescendant');
 const clear=$('#annaSearch [data-anna-clear]');if(clear)clear.hidden=!input.value;
 const askBtn=$('#annaSearch [data-anna-ask-btn]');
 const llmReady=typeof annaLlmReady==='function'&&annaLlmReady();
 if(askBtn){
  askBtn.hidden=!raw;
  askBtn.textContent=annaDialogAsking?'思考中…':(llmReady?'AI 解答 ✦':'接入 AI 提问');
  askBtn.disabled=annaDialogAsking;
 }
 input.closest?.('.search')?.classList.toggle('has-value',!!input.value);
 if(!res.norm){
  annaDialogAiHtml='';annaDialogAiQuery='';
  box.innerHTML=`<div class="anna-chips-wrap"><small>大家常问</small><div class="anna-chips">${ANNA_CHIPS.map(c=>`<button type="button" data-anna-chip="${esc(c)}">${esc(c)}</button>`).join('')}</div></div>`;
  input.setAttribute('aria-expanded','false');
  const stats=$('#annaStats');if(stats)stats.textContent='';
  return;
 }
 if(annaDialogAiQuery&&annaDialogAiQuery!==raw&&!annaDialogAsking){annaDialogAiHtml='';annaDialogAiQuery=''}
 const aiBlock=annaDialogAiHtml||`<div class="anna-dialog-ai-bar"><button type="button" class="anna-dialog-ask-trigger" data-anna-ask-trigger>${llmReady?`✦ 让安娜用 AI 解答「${esc(raw.slice(0,24))}」`:`⚙ 接入 AI 模型向安娜提问「${esc(raw.slice(0,20))}」`}</button></div>`;
 let n=0;
 const groupsHtml=res.groups.length?res.groups.map(g=>`<div class="anna-group" role="group" aria-label="${g.label}"><div class="anna-group-label">${g.label}</div>${g.items.map(s=>{const i=n++;return `<div class="anna-item" role="option" id="anna-opt-${i}" data-anna-idx="${i}" aria-selected="false"><span class="anna-kind">${g.label}</span><span class="anna-title">${annaMark(s.e.title,res.norm)}</span>${s.e.sub?`<small>${annaMark(s.e.sub,res.norm)}</small>`:''}</div>`}).join('')}</div>`).join(''):`<p class="anna-empty">${ANNA_EMPTY}</p>`;
 box.innerHTML=aiBlock+groupsHtml;
 input.setAttribute('aria-expanded',res.groups.length?'true':'false');
 const stats=$('#annaStats');if(stats)stats.textContent=res.groups.length?`找到 ${res.total} 条记录`:'';
}
function moveAnna(step){
 if(!annaFlat.length)return;
 annaActive=(annaActive+step+annaFlat.length)%annaFlat.length;
 document.querySelectorAll('#annaResults [data-anna-idx]').forEach(el=>{const on=Number(el.dataset.annaIdx)===annaActive;el.classList.toggle('active',on);el.setAttribute('aria-selected',String(on));if(on)el.scrollIntoView({block:'nearest'})});
 $('#annaInput')?.setAttribute('aria-activedescendant','anna-opt-'+annaActive);
}
function openAnnaSearch(q,autoAsk=false){
 const d=$('#annaSearch');if(!d)return;
 buildAnnaIndex();
 const val=typeof q==='string'?q:'';
 if(!d.open){
  annaOwnsLock=!dialogScrollState;
  if(annaOwnsLock)openGuideDialog(d);else d.showModal();
  annaGreeting();
 }
 const input=$('#annaInput');if(input){input.value=val;input.setAttribute('aria-expanded','false')}
 if(typeof syncAnnaLlmUI==='function')syncAnnaLlmUI();
 else if(typeof annaLlmStateText==='function')d.querySelectorAll('[data-llm-state]').forEach(el=>el.textContent=annaLlmStateText());
 renderAnnaResults();
 input?.focus();
 if(autoAsk&&val&&typeof annaLlmReady==='function'&&annaLlmReady())askAnnaInDialog(val);
}
function closeAnnaSearch(){const d=$('#annaSearch');if(d?.open)d.close()}
function pickAnna(i){
 const s=annaFlat[i];if(!s)return;
 closeAnnaSearch();
 const {kind,id,title}=s.e;
 if(kind==='character')openCharacter(id);
 else if(kind==='class')openReferenceDialog('class',id);
 else if(kind==='ability')openReferenceDialog('ability',id);
 else if(kind==='equipment')openReferenceDialog('equipment',id);
 else if(kind==='material'||kind==='place')goMap(title);
 else if(kind==='gift'){query=title;if(typeof giftCategoryFilter!=='undefined')giftCategoryFilter='all';if(typeof giftCharacterFilter!=='undefined')giftCharacterFilter='';if(typeof arenaViewState!=='undefined')arenaViewState['gifts-page']='gifts';activeCharacter=null;if($('#detail')?.open)$('#detail').close();location.hash='#gifts';render()}
 else if(kind==='article')location.hash='#guides/'+id;
 else if(kind==='page')location.hash='#'+id;
}

// 事件:按钮/弹层内部委托均挂在具体元素上,不占用 document 事件通道(verify vm 每类事件只留最后一个处理器)。
(function(){
 const d=$('#annaSearch'),input=$('#annaInput'),btn=$('#annaSearchBtn');
 btn?.addEventListener('click',()=>openAnnaSearch());
 d?.addEventListener('close',()=>{if(typeof clearInterval==='function')clearInterval(annaGreetTimer);d.querySelector('h2')?.classList.remove('anna-typing');annaFlat=[];annaActive=-1;if(annaOwnsLock){annaOwnsLock=false;releaseDialogScroll()}});
 d?.addEventListener('pointerdown',e=>{annaBackdropDown=outsideDialog(e,d)});
 d?.addEventListener('click',e=>{
  const ent=e.target.closest?.('.inline-entity-link');
  if(ent){
   if(ent.dataset.char){e.preventDefault();closeAnnaSearch();openCharacter(ent.dataset.char);return}
   if(ent.dataset.giftJump){
    e.preventDefault();
    const id=ent.dataset.giftJump,g=typeof allGifts==='function'?allGifts().find(x=>x.id===id):null;
    closeAnnaSearch();
    if(typeof arenaViewState!=='undefined')arenaViewState['gifts-page']='gifts';
    if(typeof giftCategoryFilter!=='undefined'){giftCategoryFilter='all';giftCharacterFilter='';}
    if(g)query=g.name;
    location.hash='#gifts';render();return;
   }
   if(ent.dataset.forgeMat){
    e.preventDefault();
    const name=ent.dataset.forgeMat;
    closeAnnaSearch();
    query=name;if(typeof materialKindFilter!=='undefined')materialKindFilter='all';
    if(typeof arenaViewState!=='undefined')arenaViewState['equipment-page']='materials';
    location.hash='#equipment';render();return;
   }
   if(ent.dataset.referenceType){e.preventDefault();closeAnnaSearch();openReferenceDialog(ent.dataset.referenceType,ent.dataset.referenceId);return}
   if(ent.getAttribute('href')?.startsWith('#')){closeAnnaSearch();return}
  }
  if(e.target.closest('[data-anna-llm-open]')){if(typeof openAnnaLlmSettings==='function')openAnnaLlmSettings();return}
  if(e.target.closest('[data-anna-ask-btn],[data-anna-ask-trigger]')){askAnnaInDialog();return}
  if(e.target.closest('[data-anna-ai-clear]')){annaDialogAiHtml='';annaDialogAiQuery='';renderAnnaResults();return}
  if(annaBackdropDown&&outsideDialog(e,d)){closeAnnaSearch();annaBackdropDown=false;return}
  annaBackdropDown=false;
  const item=e.target.closest?.('[data-anna-idx]');if(item){pickAnna(Number(item.dataset.annaIdx));return}
  const chip=e.target.closest?.('[data-anna-chip]');if(chip&&input){input.value=chip.dataset.annaChip;input.focus();renderAnnaResults();return}
  if(e.target.closest?.('[data-anna-clear]')&&input){input.value='';annaDialogAiHtml='';annaDialogAiQuery='';input.focus();renderAnnaResults()}
 });
 input?.addEventListener('input',e=>{if(e.isComposing)return;clearTimeout(annaDebounce);annaDebounce=setTimeout(renderAnnaResults,120)});
 input?.addEventListener('compositionstart',()=>clearTimeout(annaDebounce));
 input?.addEventListener('compositionend',()=>renderAnnaResults());
 input?.addEventListener('keydown',e=>{
  if(e.isComposing)return;
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();moveAnna(e.key==='ArrowDown'?1:-1)}
  else if(e.key==='Enter'){
   e.preventDefault();e.stopPropagation();
   if(e.shiftKey||(!annaFlat.length&&typeof annaLlmReady==='function'&&annaLlmReady())){askAnnaInDialog();return}
   if(annaActive>=0){pickAnna(annaActive);return}
   const raw=input.value.trim(), isQuestion=/[?？]|怎么|如何|为什么|哪些|哪个|好吗|推荐|培养|对比|区别|谁|多少|哪里|哪儿/.test(raw)||raw.length>=7;
   if(isQuestion&&typeof annaLlmReady==='function'&&annaLlmReady()){askAnnaInDialog();return}
   if(annaFlat.length)pickAnna(0);
   else askAnnaInDialog();
  }
  else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeAnnaSearch()}
 });
 // 全局快捷键:Ctrl/⌘+K 任何时候切换弹层;跳过输入法组合期。
 document.addEventListener('keydown',e=>{if(e.key==='k'&&(e.ctrlKey||e.metaKey)&&!e.altKey&&!e.isComposing){e.preventDefault();const d=$('#annaSearch');d?.open?closeAnnaSearch():openAnnaSearch()}});
 // 首页便笺等处的「打听一下」入口。
 document.addEventListener('click',e=>{if(e.target.closest?.('[data-anna-open]'))openAnnaSearch()});
 window.addEventListener('hashchange',closeAnnaSearch);
})();
